const driveData = $('Google Drive Yükle').first().json;
const emailData = $('Gmail Trigger').first().json;
const geminiRaw = $('Gemini AI Beleg-OCR').first().json;

let raw = '';
if (geminiRaw.choices && geminiRaw.choices[0] && geminiRaw.choices[0].message) {
  raw = geminiRaw.choices[0].message.content || '';
} else if (geminiRaw.content && geminiRaw.content.parts && geminiRaw.content.parts[0]) {
  raw = geminiRaw.content.parts[0].text || '';
} else if (geminiRaw.text) {
  raw = geminiRaw.text;
} else if (typeof geminiRaw === 'string') {
  raw = geminiRaw;
} else {
  raw = JSON.stringify(geminiRaw);
}

let jsonStr = String(raw)
  .replace(/^\`\`\`(?:json)?\s*/i, '')
  .replace(/\`\`\`\s*$/, '')
  .trim();

let aiData = {};
try {
  aiData = JSON.parse(jsonStr);
} catch (e) {
  const m = jsonStr.match(/\{[\s\S]*\}/);
  if (m) {
    try { aiData = JSON.parse(m[0]); } catch (e2) { aiData = {}; }
  }
}

const gross = parseFloat(aiData.gross_amount) || 0;
let vatRate = parseFloat(aiData.vat_rate);
if (isNaN(vatRate)) vatRate = (gross > 0 ? 19 : 0);
let net = parseFloat(aiData.net_amount);
let vatAmount = parseFloat(aiData.vat_amount);

const isRc = Boolean(aiData.reverse_charge);
if (isRc) {
  vatRate = 0;
  vatAmount = 0;
  net = gross;
} else {
  if (isNaN(net) || net <= 0) {
    net = vatRate > 0 ? (gross / (1 + (vatRate / 100))) : gross;
  }
  if (isNaN(vatAmount)) {
    vatAmount = gross - net;
  }
}

const sender = emailData.from?.text || emailData.from?.value?.[0]?.address || emailData.from?.name || 'Unbekannt';
const vendor = aiData.vendor_name || emailData.from?.value?.[0]?.name || emailData.from?.name || 'Unbekannter Lieferant';
const rawEmailText = `${emailData.subject || ''} ${emailData.text || ''} ${emailData.snippet || ''}`.toLowerCase();

// Subscription heuristic
let isRecurring = Boolean(aiData.is_recurring);
let recurringInterval = aiData.recurring_interval || (isRecurring ? 'monthly' : 'none');
if (!isRecurring && /subscription|abo|monthly|recurring|wiederkehrend|erneuerung|monatlich/i.test(rawEmailText)) {
  isRecurring = true;
  recurringInterval = 'monthly';
}

// Melih Private vs. Business heuristic
let payerType = aiData.payer_type || 'business_account';
let isDeductible = aiData.is_deductible !== false;
let taxCategory = aiData.tax_category || 'software_cloud';

if (/melih.*privat|privat.*melih/i.test(rawEmailText)) {
  payerType = 'melih_private';
  isDeductible = false;
  taxCategory = 'private_expense';
}

// Cash-basis payment date default per § 11 EStG
const invoiceDate = aiData.invoice_date || new Date().toISOString().slice(0, 10);
const paymentDate = aiData.payment_date || invoiceDate;

// Simple hash for GoBD audit trail
const hashInput = `${vendor}_${invoiceDate}_${gross}_${driveData.id || ''}`;
let hashVal = 0;
for (let i = 0; i < hashInput.length; i++) {
  hashVal = ((hashVal << 5) - hashVal) + hashInput.charCodeAt(i);
  hashVal |= 0;
}
const simulatedHash = 'sha256_' + Math.abs(hashVal).toString(16).padStart(12, '0');

return [{
  json: {
    document_id: 'DOC-' + Date.now(),
    original_filename: driveData.name || 'Beleg.pdf',
    original_file_hash: simulatedHash,
    invoice_date: invoiceDate,
    service_date: aiData.service_date || null,
    due_date: aiData.due_date || null,
    payment_date: paymentDate,
    vendor_name: vendor,
    vendor_country: (aiData.vendor_country || 'DE').toUpperCase(),
    vendor_vat_id: aiData.vendor_vat_id || null,
    invoice_number: aiData.invoice_number || null,
    description: aiData.description_summary || emailData.subject || null,
    currency: aiData.currency || 'EUR',
    gross_amount: Math.round(gross * 100) / 100,
    net_amount: Math.round(net * 100) / 100,
    vat_rate: vatRate,
    vat_amount: Math.round(vatAmount * 100) / 100,
    tax_category: taxCategory,
    euer_category: taxCategory,
    euer_mapping_version: '2026',
    reverse_charge: isRc,
    reverse_charge_reason: isRc ? (aiData.reverse_charge_reason || '§ 13b UStG / B2B Ausland') : null,
    input_vat_eligible: !isRc && isDeductible,
    is_deductible: isDeductible,
    payer_type: payerType,
    paid_by: payerType === 'melih_private' ? 'melih' : 'kemal',
    is_recurring: isRecurring,
    recurring_interval: recurringInterval,
    payment_method: aiData.payment_method || 'bank_transfer',
    drive_file_id: driveData.id || null,
    drive_web_view_link: driveData.webViewLink || null,
    email_sender: typeof sender === 'object' ? JSON.stringify(sender) : String(sender),
    email_subject: emailData.subject || null,
    raw_ai_extraction: aiData,
    status: (aiData.needs_manual_review || gross <= 0) ? 'review_needed' : 'processed'
  }
}];
